#!/usr/bin/env node

// src/cli.ts
import { mkdirSync as mkdirSync2, writeFileSync as writeFileSync4, readFileSync as readFileSync5, existsSync as existsSync3 } from "node:fs";
import { join as join6 } from "node:path";
import { homedir as homedir5 } from "node:os";
import * as readline from "node:readline";

// src/services/auth.ts
import * as fs from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";
import { createHash, randomBytes, randomUUID, timingSafeEqual } from "node:crypto";
import { createServer } from "node:http";

// src/services/openUrl.ts
import { execFile } from "node:child_process";
import { readFileSync } from "node:fs";
function run(command, args) {
  return new Promise((resolve, reject) => {
    execFile(command, args, { windowsHide: true }, (error) => {
      if (error)
        reject(error);
      else
        resolve();
    });
  });
}
function isWsl() {
  if (process.env.WSL_DISTRO_NAME || process.env.WSL_INTEROP)
    return true;
  try {
    return /microsoft/i.test(readFileSync("/proc/version", "utf-8"));
  } catch {
    return false;
  }
}
function openWithPowerShell(href) {
  const script = `Start-Process '${href.replaceAll("'", "''")}'`;
  return run("powershell.exe", [
    "-NoProfile",
    "-NonInteractive",
    "-EncodedCommand",
    Buffer.from(script, "utf16le").toString("base64")
  ]);
}
async function openUrl(url) {
  const href = url.toString();
  if (!/^https?:\/\//i.test(href)) {
    throw new Error("Refusing to open non-http URL");
  }
  if (process.platform === "win32") {
    try {
      await run("rundll32.exe", ["url.dll,FileProtocolHandler", href]);
      return;
    } catch {}
    await run("cmd.exe", ["/c", "start", '""', href]);
    return;
  }
  if (process.platform === "darwin") {
    await run("open", [href]);
    return;
  }
  if (isWsl()) {
    try {
      await run("wslview", [href]);
      return;
    } catch {}
    try {
      await openWithPowerShell(href);
      return;
    } catch {}
  }
  await run("xdg-open", [href]);
}

// src/version.ts
var PLUGIN_VERSION = "2.2.0";

// src/services/auth.ts
var CREDENTIALS_DIR = join(homedir(), ".supermemory-opencode");
var CREDENTIALS_FILE = join(CREDENTIALS_DIR, "credentials.json");
var CLIENT_FILE = join(CREDENTIALS_DIR, "oauth-client.json");
var LOCK_FILE = join(CREDENTIALS_DIR, "auth.lock");
var AUTH_PORT = 19880;
var REDIRECT_URI = `http://127.0.0.1:${AUTH_PORT}/callback`;
var OAUTH_SCOPE = "openid profile email offline_access";
var REFRESH_TIMEOUT = 3000;
var REFRESH_REQUEST_TIMEOUT = 1e4;
var REFRESH_SKEW = 60000;
var configuredAuthTimeout = Number(process.env.SUPERMEMORY_AUTH_TIMEOUT);
var AUTH_TIMEOUT = Number.isFinite(configuredAuthTimeout) && configuredAuthTimeout > 0 ? configuredAuthTimeout : 5 * 60000;
function callbackPage(title, color, heading, message) {
  return `<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>${title} - Supermemory</title></head>
<body style="font-family: system-ui; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; background: #0a0a0a; color: #fafafa;">
<div style="text-align: center;"><h1 style="color: ${color};">${heading}</h1><p>${message}</p></div>
</body></html>`;
}
var AUTH_SUCCESS_HTML = callbackPage("Connected", "#22c55e", "Connected!", "You can close this window and return to OpenCode.");
var AUTH_DENIED_HTML = callbackPage("Authorization denied", "#ef4444", "Authorization denied", "Supermemory was not connected. Return to OpenCode and run login again to retry.");
var AUTH_FAILED_HTML = callbackPage("Connection failed", "#ef4444", "Connection failed", "Return to OpenCode and try login again.");

class AuthError extends Error {
  code;
  constructor(message, code) {
    super(message);
    this.code = code;
  }
}
function authRequired() {
  return new AuthError("Supermemory authentication required. Run `bunx opencode-supermemory@latest login` (or /supermemory-login), or set SUPERMEMORY_API_KEY.", "AUTH_REQUIRED");
}
function readJson(file) {
  try {
    const value = JSON.parse(fs.readFileSync(file, "utf-8"));
    return value && typeof value === "object" && !Array.isArray(value) ? value : null;
  } catch {
    return null;
  }
}
var credentialCache;
function loadCredentialData() {
  let key;
  try {
    const stat = fs.statSync(CREDENTIALS_FILE);
    key = `${stat.dev}:${stat.ino}:${stat.size}:${stat.mtimeMs}`;
  } catch {
    credentialCache = undefined;
    return null;
  }
  if (credentialCache?.key !== key) {
    const data = readJson(CREDENTIALS_FILE);
    credentialCache = {
      key,
      data: data?.type === "oauth" || data && typeof data.apiKey === "string" && data.apiKey ? data : null
    };
  }
  return credentialCache.data ? { ...credentialCache.data } : null;
}
function loadCredentials() {
  const data = loadCredentialData();
  return data?.type === "oauth" ? undefined : data?.apiKey;
}
function writeJson(file, data) {
  fs.mkdirSync(CREDENTIALS_DIR, { recursive: true, mode: 448 });
  const temporary = `${file}.${randomUUID()}.tmp`;
  try {
    fs.writeFileSync(temporary, JSON.stringify(data, null, 2), { mode: 384, flag: "wx" });
    fs.renameSync(temporary, file);
  } finally {
    fs.rmSync(temporary, { force: true });
  }
}
function recoverAbandonedLock() {
  let recovery;
  let linked = false;
  try {
    const original = fs.statSync(LOCK_FILE);
    recovery = `${LOCK_FILE}.${original.dev}.${original.ino}.recovery`;
    fs.linkSync(LOCK_FILE, recovery);
    linked = true;
    const snapshot = fs.statSync(recovery);
    if (snapshot.ino !== original.ino || snapshot.dev !== original.dev)
      return;
    const owner = readJson(recovery);
    let abandoned = false;
    if (owner && Number.isInteger(owner.pid) && owner.pid > 0) {
      try {
        process.kill(owner.pid, 0);
      } catch (error) {
        abandoned = error.code === "ESRCH";
      }
    } else {
      abandoned = Date.now() - snapshot.mtimeMs > 10 * 60000;
    }
    if (abandoned) {
      const current = fs.statSync(LOCK_FILE);
      if (current.ino === original.ino && current.dev === original.dev)
        fs.unlinkSync(LOCK_FILE);
    }
  } catch (error) {
    if (!["ENOENT", "EEXIST"].includes(error.code ?? ""))
      throw error;
  } finally {
    if (linked && recovery)
      fs.rmSync(recovery, { force: true });
  }
}
async function withAuthLock(action, timeoutMs) {
  fs.mkdirSync(CREDENTIALS_DIR, { recursive: true, mode: 448 });
  const deadline = Date.now() + timeoutMs;
  let descriptor;
  while (descriptor === undefined) {
    try {
      descriptor = fs.openSync(LOCK_FILE, "wx", 384);
    } catch (error) {
      if (error.code !== "EEXIST")
        throw error;
      recoverAbandonedLock();
      if (Date.now() >= deadline)
        throw new Error("Supermemory authentication is busy. Try again.");
      await new Promise((resolve) => setTimeout(resolve, 50));
    }
  }
  try {
    fs.writeFileSync(descriptor, JSON.stringify({ pid: process.pid }));
    return await action(Math.max(1, deadline - Date.now()));
  } finally {
    fs.closeSync(descriptor);
    fs.rmSync(LOCK_FILE, { force: true });
  }
}
function secureUrl(value) {
  const url = new URL(value);
  const loopback = ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname);
  if (url.username || url.password || url.hash || url.search || url.protocol !== "https:" && !(url.protocol === "http:" && loopback)) {
    throw new Error("OAuth requires HTTPS (HTTP is allowed only for loopback development).");
  }
  return url.toString().replace(/\/+$/, "");
}
function getOAuthConfig(baseUrl, issuer, mcpUrl) {
  return {
    apiBaseUrl: secureUrl(baseUrl),
    issuer: secureUrl(issuer),
    resource: secureUrl(mcpUrl)
  };
}
function sameConfig(credentials, config) {
  return credentials?.apiBaseUrl === config.apiBaseUrl && credentials?.issuer === config.issuer && credentials?.resource === config.resource;
}
function hasOAuthCredentials(config) {
  const credentials = loadCredentialData();
  return credentials?.type === "oauth" && sameConfig(credentials, config) && (!!credentials.refreshToken || !!credentials.accessToken && credentials.expiresAt > Date.now() + REFRESH_SKEW);
}
function issuerEndpoint(value, issuer) {
  const endpoint = secureUrl(value);
  if (new URL(endpoint).origin !== new URL(issuer).origin) {
    throw new Error("OAuth endpoint does not belong to the configured issuer.");
  }
  return endpoint;
